def find_changed_pairs(inputs, outputs):
    """Identify which (input, output) pairs actually differ."""
    changed = []
    for i in range(len(inputs)):
        if inputs[i] != outputs[i]:
            changed.append((i, inputs[i], outputs[i]))
    return changed

def find_minimal_edit(s_in, s_out):
    """Find the minimal edit needed to transform s_in to s_out."""
    # For now, let's focus on finding patterns rather than exact edits
    # We'll look for common substitutions

    # Simple approach: find first difference and see what we can generalize
    min_len = min(len(s_in), len(s_out))

    # Look for character substitutions
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            # Found a difference at position i
            old_char = s_in[i]
            new_char = s_out[i]
            return (old_char, new_char, i)

    # If we get here, one string is prefix of the other
    if len(s_in) < len(s_out):
        # Addition occurred
        return (s_in[-1] if s_in else '', s_out[len(s_in)], len(s_in))
    elif len(s_in) > len(s_out):
        # Deletion occurred  
        return (s_in[len(s_out)], '', len(s_out))

    return ('', '', -1)

def propose_rule_candidates(s_in, s_out):
    """Propose rule candidates for transforming s_in to s_out."""
    # Start with most specific and work to general
    candidates = []

    # Get minimal edit
    old_sub, new_sub, pos = find_minimal_edit(s_in, s_out)

    if old_sub and new_sub:
        candidates.append((old_sub, new_sub))

    # Add some generalizations
    # Try longer patterns if possible
    if len(s_in) > 1 and len(s_out) > 1:
        # Try 2-character patterns
        if len(s_in) >= 2 and len(s_out) >= 2:
            candidates.append((s_in[:2], s_out[:2]))

        # Try 3-character patterns  
        if len(s_in) >= 3 and len(s_out) >= 3:
            candidates.append((s_in[:3], s_out[:3]))

    # Add reverse candidates
    candidates.append((s_in, s_out))

    return candidates

